"""Training and evaluation examples for the document extraction model (models/docextract.py).

Three label sources, all of them exact truth or a dataset's own labels (nothing here is produced by a model):
  * pages generated by `pages` (truth `fields`, `keyValues`, from the renderer's own DOM geometry);
  * CORD v2 train/test annotations (CC BY 4.0): menu / sub_total / total categories, `is_key` words and group ids;
  * the same generated and CORD pages read by our own OCR: its words are aligned to the truth words by box overlap and take the
    labels of the truth words they cover. OCR words that cover no annotated word are "O" on generated pages (every printed word
    is annotated there) and unlabeled (-100) on CORD (its annotation is partial). The OCR only supplies the words and their boxes.

An example is a dict: `texts`, `boxes` (page pixels), `width`, `height`, the featurize() arrays, labels `tags`, `roles`, `group_ptr`,
`kv_ptr` (word indices or -100), `doc`, and `truth` (language-independent field instances, used by the metrics).

CLI:  uv run python -m train.docextract_data build --pages DIR --split train --out FILE [--ocr DIR] [--cord DIR --cord-split train]
"""

from __future__ import annotations

import argparse
import json
import pickle
import unicodedata
from collections import defaultdict
from pathlib import Path

import numpy as np

from models.docextract import (
    CLASS_ID,
    CLASSES,
    DOC_TYPES,
    GROUP_CLASSES,
    LINE_CLASSES,
    TAX_CLASSES,
    featurize,
)

IGNORE = -100
ROLE_ID = {"O": 0, "B-KEY": 1, "I-KEY": 2, "B-VAL": 3, "I-VAL": 4}


def nfc(s: str) -> str:
    return unicodedata.normalize("NFC", s)


def page_words(page: dict) -> tuple[list[str], list[list[float]]]:
    """Words of an oneocr.page page in document order (blocks, lines, words)."""
    texts, boxes = [], []
    for b in page["blocks"]:
        for ln in b["lines"]:
            for w in ln["words"]:
                t = nfc(w["text"]).strip()
                if t:
                    texts.append(t)
                    boxes.append([float(v) for v in w["bounds"]])
    return texts, boxes


# ---------------------------------------------------------------------------------------------------------------------
# truth structure


def truth_structure(page: dict, nwords: int) -> dict:
    """Field instances, key/value pairs and groups of a generated page, in terms of truth word indices."""
    kind = page.get("documentType", "other")
    insts = []
    tax_seen: dict[str, int] = defaultdict(int)
    for f in page.get("fields", []):
        cls = f["id"]
        if cls not in CLASS_ID:
            continue
        if cls in LINE_CLASSES and f["lineItem"] is not None:
            g = ("line", int(f["lineItem"]))
        elif cls in TAX_CLASSES:
            g = ("tax", tax_seen[cls])  # the k-th tax-breakdown row holds the k-th rate, taxable amount and tax amount
            tax_seen[cls] += 1
        else:
            g = None
        insts.append({"cls": cls, "words": list(f["words"]), "group": g})
    kvs = [{"key": list(k["key"]), "value": list(k["value"])} for k in page.get("keyValues", []) if k["key"] and k["value"]]
    return {"doc": kind, "fields": insts, "kv": kvs}


def doc_index(kind: str) -> int:
    return DOC_TYPES.index(kind) if kind in DOC_TYPES else 2


def build_labels(n: int, owner_sets: list[list[int]], fields: list[dict], kvs: list[dict]) -> dict:
    """Labels on a sequence of n words.

    owner_sets[t] lists the sequence words that represent truth word t (one word for truth input; the covering OCR words for OCR
    input). Fields and kv pairs refer to truth word indices. Each sequence word takes the instance of the truth word that
    claimed it first (a word never carries two fields; the generator guarantees none overlap).
    """
    inst_of = [-1] * n  # sequence word -> field instance
    kv_of: list[tuple[int, str] | None] = [None] * n
    for fi, f in enumerate(fields):
        for t in f["words"]:
            for o in owner_sets[t]:
                if inst_of[o] < 0:
                    inst_of[o] = fi
    for ki, kv in enumerate(kvs):
        for side, key in (("K", "key"), ("V", "value")):
            for t in kv[key]:
                for o in owner_sets[t]:
                    if kv_of[o] is None:
                        kv_of[o] = (ki, side)
    return {"inst_of": inst_of, "kv_of": kv_of}


def labels_to_arrays(n: int, fields: list[dict], inst_of: list[int], kv_of: list, known: np.ndarray | None = None) -> dict:
    tags = np.zeros(n, dtype=np.int64)
    roles = np.zeros(n, dtype=np.int64)
    gptr = np.full(n, IGNORE, dtype=np.int64)
    kptr = np.full(n, IGNORE, dtype=np.int64)
    for o in range(n):
        fi = inst_of[o]
        if fi >= 0:
            c = CLASS_ID[fields[fi]["cls"]]
            same = o > 0 and inst_of[o - 1] == fi
            tags[o] = 2 + 2 * c if same else 1 + 2 * c
        if kv_of[o] is not None:
            ki, side = kv_of[o]
            same = o > 0 and kv_of[o - 1] == kv_of[o]
            roles[o] = ROLE_ID[("I-" if same else "B-") + ("KEY" if side == "K" else "VAL")]
    # pointers: anchor = first sequence word of the group / of the key
    gfirst: dict = {}
    for o in range(n):
        fi = inst_of[o]
        if fi >= 0 and fields[fi]["group"] is not None:
            gfirst.setdefault(fields[fi]["group"], o)
    kfirst: dict = {}
    for o in range(n):
        if kv_of[o] is not None and kv_of[o][1] == "K":
            kfirst.setdefault(kv_of[o][0], o)
    for o in range(n):
        fi = inst_of[o]
        if fi >= 0 and fields[fi]["group"] is not None:
            gptr[o] = gfirst[fields[fi]["group"]]
        if kv_of[o] is not None:
            ki, side = kv_of[o]
            kptr[o] = kfirst.get(ki, o) if side == "V" else o
    if known is not None:
        tags[~known] = IGNORE
        roles[~known] = IGNORE
        gptr[~known] = IGNORE
        kptr[~known] = IGNORE
    return {"tags": tags, "roles": roles, "group_ptr": gptr, "kv_ptr": kptr}


def make_example(texts, boxes, width, height, doc, labels, truth, meta) -> dict:
    ex = featurize(texts, boxes, width, height)
    ex.update(labels)
    ex.update(
        {
            "texts": texts,
            "boxes": np.asarray(boxes, dtype=np.float32),
            "width": width,
            "height": height,
            "doc": doc,
            "truth": truth,
            "meta": meta,
        }
    )
    return ex


def truth_text(words: list[str], idx: list[int]) -> str:
    return " ".join(words[i] for i in idx)


def eval_truth(page_struct: dict, truth_texts: list[str]) -> dict:
    """What the metrics compare against: field instances with their text, groups and key/value texts."""
    fields = [{"cls": f["cls"], "text": truth_text(truth_texts, f["words"]), "group": f["group"]} for f in page_struct["fields"]]
    kv = [{"key": truth_text(truth_texts, k["key"]), "value": truth_text(truth_texts, k["value"])} for k in page_struct["kv"]]
    return {"doc": page_struct["doc"], "fields": fields, "kv": kv}


# ---------------------------------------------------------------------------------------------------------------------
# alignment of OCR words to truth words


def align(t_boxes: np.ndarray, o_boxes: np.ndarray, min_cover: float = 0.5) -> tuple[list[list[int]], np.ndarray]:
    """For each truth word the OCR words covering it, and for each OCR word the index of the truth word it overlaps most (-1: none).

    A pair counts when the intersection covers at least `min_cover` of the smaller box. Truth boxes are the browser's line-height
    word rectangles; OCR boxes are the library's own word boxes in the same pixel frame.
    """
    t, o = len(t_boxes), len(o_boxes)
    if t == 0 or o == 0:
        return [[] for _ in range(t)], np.full(o, -1)
    ix0 = np.maximum(t_boxes[:, None, 0], o_boxes[None, :, 0])
    iy0 = np.maximum(t_boxes[:, None, 1], o_boxes[None, :, 1])
    ix1 = np.minimum(t_boxes[:, None, 2], o_boxes[None, :, 2])
    iy1 = np.minimum(t_boxes[:, None, 3], o_boxes[None, :, 3])
    inter = np.clip(ix1 - ix0, 0, None) * np.clip(iy1 - iy0, 0, None)
    at = np.maximum((t_boxes[:, 2] - t_boxes[:, 0]) * (t_boxes[:, 3] - t_boxes[:, 1]), 1e-6)
    ao = np.maximum((o_boxes[:, 2] - o_boxes[:, 0]) * (o_boxes[:, 3] - o_boxes[:, 1]), 1e-6)
    cover = inter / np.minimum(at[:, None], ao[None, :])
    ok = cover >= min_cover
    inter_ok = np.where(ok, inter, 0.0)
    dom = np.where(inter_ok.max(0) > 0, inter_ok.argmax(0), -1)  # OCR word -> truth word it overlaps most
    owners = [[int(j) for j in np.nonzero(ok[i] & (dom == i))[0]] for i in range(t)]
    return owners, dom


def ocr_example(
    truth_page: dict,
    ocr_page: dict,
    kind_meta: dict,
    partial: bool = False,
    tstruct: dict | None = None,
    ttexts: list[str] | None = None,
    tboxes: list | None = None,
    labelled_words: np.ndarray | None = None,
) -> tuple[dict, float]:
    """Example from OCR words. `labelled_words[t]` (CORD) marks truth words whose label is known; other OCR words are unlabeled."""
    otexts, oboxes = page_words(ocr_page)
    if not otexts:
        raise ValueError("no OCR words")
    owners, dom = align(np.asarray(tboxes, dtype=np.float64), np.asarray(oboxes, dtype=np.float64))
    lab = build_labels(len(otexts), owners, tstruct["fields"], tstruct["kv"])
    known = None
    if partial:
        known = np.array([d >= 0 and bool(labelled_words[d]) for d in dom])
    arr = labels_to_arrays(len(otexts), tstruct["fields"], lab["inst_of"], lab["kv_of"], known)
    cov = sum(1 for o in owners if o) / max(len(owners), 1)
    ex = make_example(
        otexts,
        oboxes,
        ocr_page["width"],
        ocr_page["height"],
        doc_index(tstruct["doc"]),
        arr,
        eval_truth(tstruct, ttexts),
        {**kind_meta, "input": "ocr", "partial": partial},
    )
    if partial:
        ex["known"] = known
    return ex, cov


# ---------------------------------------------------------------------------------------------------------------------
# generated pages


def load_pages(
    root: Path, split: str, ocr_root: Path | None, limit: int | None = None, kinds: set[str] | None = None
) -> tuple[list, list, dict]:
    truth_ex, ocr_ex = [], []
    stats = defaultdict(float)
    ids = [json.loads(line) for line in (root / split / "manifest.jsonl").read_text().splitlines()]
    ids.sort(key=lambda m: m["id"])
    for m in ids[:limit]:
        doc = json.loads((root / split / "truth" / f"{m['id']}.json").read_text(encoding="utf-8"))
        page = doc["pages"][0]
        ttexts, tboxes = page_words(page)
        if len(ttexts) != m["words"]:
            # words with empty text were dropped by page_words; the field indices would shift, so skip such a page
            stats["skipped_empty_word"] += 1
            continue
        kind = page.get("documentType", m["kind"])
        if kinds and kind not in kinds:
            continue
        tstruct = truth_structure(page, len(ttexts))
        meta = {"id": m["id"], "kind": kind, "profile": m.get("profile"), "split": split, "source": "generated"}
        lab = build_labels(len(ttexts), [[i] for i in range(len(ttexts))], tstruct["fields"], tstruct["kv"])
        arr = labels_to_arrays(len(ttexts), tstruct["fields"], lab["inst_of"], lab["kv_of"])
        truth_ex.append(
            make_example(
                ttexts, tboxes, page["width"], page["height"], doc_index(kind), arr, eval_truth(tstruct, ttexts), {**meta, "input": "truth"}
            )
        )
        stats["truth_pages"] += 1
        if ocr_root is not None:
            op = ocr_root / split / f"{m['id']}.page.json"
            if op.exists():
                ocr_page = json.loads(op.read_text(encoding="utf-8"))["pages"][0]
                try:
                    ex, cov = ocr_example(page, ocr_page, meta, tstruct=tstruct, ttexts=ttexts, tboxes=tboxes)
                except ValueError:
                    stats["ocr_empty"] += 1
                    continue
                ocr_ex.append(ex)
                stats["ocr_pages"] += 1
                stats["truth_word_coverage_sum"] += cov
                stats["ocr_words"] += len(ex["texts"])
                stats["truth_words"] += len(ttexts)
    return truth_ex, ocr_ex, dict(stats)


# ---------------------------------------------------------------------------------------------------------------------
# CORD v2

CORD_FIELD = {
    "menu.nm": "receipt.itemName",
    "menu.cnt": "receipt.quantity",
    "menu.unitprice": "receipt.unitPrice",
    "menu.price": "receipt.amount",
    "sub_total.subtotal_price": "receipt.subtotal",
    "sub_total.tax_price": "receipt.tax",
    "total.total_price": "receipt.total",
}
CORD_OTHER = {"menu.etc", "sub_total.etc", "total.etc", "void_menu.nm", "void_menu.price", "void_menu.etc"}  # known non-fields


def cord_page(rec: dict) -> dict:
    gt = json.loads(rec["ground_truth"])
    meta = gt["meta"]
    lines = gt["valid_line"]
    words = []
    for li, ln in enumerate(lines):
        for w in ln["words"]:
            q = w["quad"]
            xs = [q["x1"], q["x2"], q["x3"], q["x4"]]
            ys = [q["y1"], q["y2"], q["y3"], q["y4"]]
            txt = nfc(w["text"]).strip()
            if not txt:
                continue
            words.append((w["row_id"], min(xs), [min(xs), min(ys), max(xs), max(ys)], txt, li, bool(w["is_key"])))
    words.sort(key=lambda r: (r[0], r[1]))
    texts = [w[3] for w in words]
    boxes = [w[2] for w in words]
    line_of = [w[4] for w in words]
    is_key = [w[5] for w in words]
    fields, kvs = [], []
    known = np.zeros(len(words), dtype=bool)  # word whose field tag is known (mapped field or explicit "other")
    for li, ln in enumerate(lines):
        idx = [i for i, lo in enumerate(line_of) if lo == li]
        keys = [i for i in idx if is_key[i]]
        vals = [i for i in idx if not is_key[i]]
        cat = ln["category"]
        if keys and vals:
            kvs.append({"key": keys, "value": vals})
        if cat in CORD_FIELD:
            g = ("line", ln["group_id"]) if cat.startswith("menu.") else None
            fields.append({"cls": CORD_FIELD[cat], "words": vals, "group": g})
            known[idx] = True
        elif cat in CORD_OTHER:
            known[idx] = True
    return {
        "texts": texts,
        "boxes": boxes,
        "w": meta["image_size"]["width"],
        "h": meta["image_size"]["height"],
        "fields": fields,
        "kv": kvs,
        "known": known,
    }


def load_cord(root: Path, split: str, ocr_root: Path | None, limit: int | None = None) -> tuple[list, list, dict]:
    ann = root / "annotations" / f"{split}.jsonl"
    drop = set(json.loads((root / "dedup.json").read_text()).get("drop", []))
    truth_ex, ocr_ex, stats = [], [], defaultdict(float)
    for line in ann.read_text(encoding="utf-8").splitlines()[:limit]:
        rec = json.loads(line)
        if rec["id"] in drop:
            stats["dedup_dropped"] += 1
            continue
        pg = cord_page(rec)
        if not pg["texts"]:
            continue
        tstruct = {"doc": "receipt", "fields": pg["fields"], "kv": pg["kv"]}
        meta = {"id": rec["id"], "kind": "receipt", "split": split, "source": "cord"}
        n = len(pg["texts"])
        lab = build_labels(n, [[i] for i in range(n)], pg["fields"], pg["kv"])
        arr = labels_to_arrays(n, pg["fields"], lab["inst_of"], lab["kv_of"], pg["known"])
        # kv roles are known for every annotated word, only the field tags depend on the category mapping
        arr_roles = labels_to_arrays(n, pg["fields"], lab["inst_of"], lab["kv_of"])
        arr["roles"], arr["kv_ptr"] = arr_roles["roles"], arr_roles["kv_ptr"]
        arr["tags"][~pg["known"]] = IGNORE
        ex = make_example(
            pg["texts"],
            pg["boxes"],
            pg["w"],
            pg["h"],
            1,
            arr,
            eval_truth(tstruct, pg["texts"]),
            {**meta, "input": "truth", "partial": True},
        )
        ex["known"] = pg["known"]
        truth_ex.append(ex)
        stats["truth_pages"] += 1
        if ocr_root is not None:
            op = ocr_root / split / f"{rec['id'].split('/')[-1]}.page.json"
            if op.exists():
                ocr_page = json.loads(op.read_text(encoding="utf-8"))["pages"][0]
                try:
                    oex, cov = ocr_example(
                        None,
                        ocr_page,
                        meta,
                        partial=True,
                        tstruct=tstruct,
                        ttexts=pg["texts"],
                        tboxes=pg["boxes"],
                        labelled_words=np.ones(n, dtype=bool),
                    )
                except ValueError:
                    continue
                # which OCR words are labeled: those overlapping an annotated word; field tags only where the category is mapped
                _, dom = align(np.asarray(pg["boxes"], dtype=np.float64), np.asarray(oex["boxes"], dtype=np.float64))
                kn = np.array([d >= 0 and bool(pg["known"][d]) for d in dom])
                ann_w = np.array([d >= 0 for d in dom])
                oex["tags"][~kn] = IGNORE
                oex["roles"][~ann_w] = IGNORE
                oex["group_ptr"][~kn] = IGNORE
                oex["kv_ptr"][~ann_w] = IGNORE
                oex["known"] = kn
                ocr_ex.append(oex)
                stats["ocr_pages"] += 1
                stats["truth_word_coverage_sum"] += cov
    return truth_ex, ocr_ex, dict(stats)


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("cmd", choices=["build"])
    ap.add_argument("--pages", help="generated page set root (contains <split>/)")
    ap.add_argument("--split", default="train")
    ap.add_argument("--ocr", help="directory with <split>/<id>.page.json from the OCR run")
    ap.add_argument("--cord", help="CORD root (…/cord/v2)")
    ap.add_argument("--cord-split", default="train")
    ap.add_argument("--cord-ocr", help="directory with <split>/<n>.page.json for CORD images")
    ap.add_argument("--limit", type=int)
    ap.add_argument("--out", required=True)
    a = ap.parse_args()
    out = {"generated": {}, "cord": {}}
    if a.pages:
        t, o, st = load_pages(Path(a.pages), a.split, Path(a.ocr) if a.ocr else None, a.limit)
        out["generated"] = {"truth": t, "ocr": o, "stats": st}
        print("generated", st)
    if a.cord:
        t, o, st = load_cord(Path(a.cord), a.cord_split, Path(a.cord_ocr) if a.cord_ocr else None, a.limit)
        out["cord"] = {"truth": t, "ocr": o, "stats": st}
        print("cord", st)
    Path(a.out).parent.mkdir(parents=True, exist_ok=True)
    with open(a.out, "wb") as f:
        pickle.dump(out, f, protocol=5)
    print("classes", len(CLASSES), "group classes", len(GROUP_CLASSES))


if __name__ == "__main__":
    main()
